package ferry

import zio.*
import zio.test.*

import ferry.testkit.tla.{Behaviours, Tlc, Value}

/**
 * Model → code: random behaviours of every conforming configuration of `formal/Ferry.tla`, generated by TLC, replay
 * step by step through the code's protocol with no divergence. `FERRY_SAMPLES` sets the number of behaviours.
 */
object ModelReplaySpec extends ZIOSpecDefault:

  private val count = sys.env.get("FERRY_SAMPLES").flatMap(_.toIntOption).getOrElse(100)

  /** The behaviours of `config`, or the reason there are none (TLC missing: skipped; TLC failing: a tool error). */
  def behaviours(config: String, seed: Long = 1L): Either[Tlc.Verdict, Vector[Behaviours.Behaviour]] =
    Tlc.formal.toRight(Tlc.Verdict.Skipped("no formal/ directory")).flatMap { formal =>
      Behaviours.generate(formal, "Ferry", config, count, depth = 40, seed)
    }

  def actionNames(b: Behaviours.Behaviour): Set[String] =
    b.drop(1).map(_("act")).collect { case Value.Rec(fs) => fs("name") }.collect { case Value.Str(n) => n }.toSet

  def spec = suite("Behaviours of the model replay through the code")(
    List("Ferry", "FerryBatchOnly", "FerryMake").map { config =>
      test(config) {
        for
          generated <- ZIO.attemptBlocking(behaviours(config)).orDie
          formal   = Tlc.formal.get
          instance = ModelReplay.instance(formal, config)
          verdicts = generated.map(_.map(b => ModelReplay.replay(b, instance)))
          diverged = verdicts.toOption.toVector.flatten.collect { case d: ModelReplay.Verdict.Diverged => d }
          seen     = generated.toOption.toVector.flatten.flatMap(actionNames).toSet
        yield assertTrue(generated.isRight, diverged.isEmpty, generated.toOption.get.size == count) &&
          assertTrue(seen.contains("Take"), seen.contains("Complete"), seen.contains("Cancel"), seen.contains("Close"))
      }
    }*
  ) @@ TestAspect.sequential @@ TestAspect.withLiveClock @@ TestAspect.timeout(10.minutes)
